// Explicit work-sheet comparison. Loading retains live inputs and never grants execution authority.
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;

internal sealed partial class ExperimentShell {
 async void ShowWorkSheet(string name){
  try{
   if(!await Send(LocalApi.D("action","template-inspect","name",name))||closing||form.IsDisposed)return;
   var result=lastCommandResult;if(result==null)return;if(!OwnedActiveWindow()){Say("Work sheet inspected. Return to the application and reopen it to compare inputs.");return;}
   ShowWorkSheetReview(name,result);
  }catch(OperationCanceledException){if(!closing&&!form.IsDisposed)Say("Work-sheet inspection was cancelled. Reopen it to compare current inputs.");}
  catch(Exception error){NativeDiagnostics.Write("Work-sheet inspection failed",error);if(!closing&&!form.IsDisposed)Say(error.Message,true);}
 }
 static string SheetGoal(string goal){switch(goal){case "prepare":return "Prepare";case "insert":return "Insert";case "place":return "Place piece";case "orient":return "Orient piece";case "finish-buffer":return "Finish buffer";case "block":return "Build block";case "endgame":return "Finish orbit";default:return "Unknown historical goal";}}
 string SheetRowText(Dictionary<string,object> row,string side){
  string display=Text(Value(row,side+"_display"));if(display.Length>0)return display;
  if(side=="saved"&&Text(Value(row,"status"))=="unknown")return "Not recorded";
  var value=Value(row,side);if(value==null)return "Not assigned";string key=Text(Value(row,"key"));
  if(key=="orbit")return OrbitName(Number(value));if(key=="goal")return SheetGoal(Text(value));if(key=="prefix")return Object.Equals(value,true)?"Every turn":"Final result only";
  if(key=="reference")return Items(value).Length==0?"Identity reference":Items(value).Length+" explicit turns · see Reference";
  return "Exact record available in details";
 }
 string SheetRowDetail(Dictionary<string,object> row,string side){string detail=Text(Value(row,side+"_detail"));return detail.Length>0?detail:Text(Value(row,"label"))+" · "+side+" canonical record\r\n"+api.Json(Value(row,side));}
 TextBox SheetReadout(string text,string accessible){return new TextBox{Text=text.Replace("\r\n","\n").Replace("\n","\r\n"),ReadOnly=true,Multiline=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Both,WordWrap=false,BorderStyle=BorderStyle.None,AccessibleName=accessible,BackColor=Color.FromArgb(25,33,41),ForeColor=Ink};}
 void SheetCopyMenu(Control control,string detail){var menu=new ContextMenuStrip();menu.Items.Add("Copy complete mathematical and canonical details",null,delegate{try{Clipboard.SetText(detail);}catch(Exception error){Say("Copy did not complete: "+error.Message,true);}});control.ContextMenuStrip=menu;control.Disposed+=delegate{menu.Dispose();};tips.SetToolTip(control,detail);control.AccessibleDescription=detail;}
 void ShowWorkSheetReview(string name,Dictionary<string,object> initial){
  using(var dialog=ToolDialog("Reuse work sheet · "+name,900,670)){
   dialog.MinimumSize=new Size(690,520);var grid=ToolLayout(dialog,0,70,-1,32,0,0,46);var summary=ToolLabel("");summary.AutoEllipsis=false;summary.AccessibleName="Saved work-sheet method";grid.Controls.Add(summary,0,0);FitToolTextRow(grid,summary,0);
   var contextStrip=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1};contextStrip.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,60));contextStrip.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,40));Label nextReadout=ToolLabel(""),policyReadout=ToolLabel("");nextReadout.AutoEllipsis=policyReadout.AutoEllipsis=false;nextReadout.AccessibleName="Work sheet locked Next bookmark";policyReadout.AccessibleName="Current protection for work sheet";contextStrip.Controls.Add(nextReadout,0,0);contextStrip.Controls.Add(policyReadout,1,0);grid.Controls.Add(contextStrip,0,1);
   var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Paper,AccessibleName="Saved inputs compared with current inputs"};var comparison=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,ColumnCount=3,Padding=new Padding(0,0,10,0)};comparison.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,20));comparison.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,40));comparison.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,40));scroll.Controls.Add(comparison);grid.Controls.Add(scroll,0,2);
   var toggles=ToolRow();var expand=new CheckBox{Text="Show fixed steps and revisions",AutoSize=true,AccessibleName="Expand saved method details"};var unchanged=new CheckBox{Text="Show unchanged details",AutoSize=true,AccessibleName="Show unchanged input comparisons"};toggles.Controls.Add(expand);toggles.Controls.Add(unchanged);grid.Controls.Add(toggles,0,3);var details=new TabControl{Dock=DockStyle.Fill,AccessibleName="Fixed work-sheet method details",Visible=false};grid.Controls.Add(details,0,4);expand.CheckedChanged+=delegate{if(expand.Checked){var area=Screen.FromControl(dialog).WorkingArea;var bounds=dialog.Bounds;bounds.Height=Math.Max(bounds.Height,665);dialog.Bounds=ExperimentWindowPlacement.Clamp(bounds,area,dialog.MinimumSize);}details.Visible=expand.Checked;grid.RowStyles[4].Height=expand.Checked?145:0;};
   var status=ToolLabel("");status.AutoEllipsis=false;status.AccessibleName="Work-sheet confirmation status";grid.Controls.Add(status,0,5);FitToolTextRow(grid,status,5);var actions=ToolRow();Button load=ToolButton("Load fixed steps with these inputs"),refresh=ToolButton("Refresh comparison"),cancel=ToolButton("Cancel");cancel.DialogResult=DialogResult.Cancel;actions.Controls.Add(load);actions.Controls.Add(refresh);actions.Controls.Add(cancel);grid.Controls.Add(actions,0,6);dialog.CancelButton=cancel;
   load.AccessibleDescription="Load the saved fixed steps, reference and goal; keep current inputs and protection. No steps are retargeted. Review the complete operation again before execution.";tips.SetToolTip(load,load.AccessibleDescription);
   Dictionary<string,object> displayed=initial;bool applying=false;string failureNotice=null;
   Action<string> reject=delegate(string reason){failureNotice=reason;status.Text=reason;load.Enabled=false;};
   Action render=delegate{
    var sheet=Map(Value(displayed,"sheet"));var inspection=Map(Value(displayed,"inspection"));var draft=Map(Value(sheet,"draft"));string token=Text(Value(displayed,"confirmation"));bool valid=Object.Equals(Value(inspection,"valid"),true),sameOrbit=Object.Equals(Value(inspection,"orbit_match"),true);
    int changedSources=Items(Value(inspection,"macro_sources")).Select(Map).Count(source=>Text(Value(source,"status"))!="match");
    summary.Text=name+" · "+SheetGoal(Text(Value(sheet,"goal")))+"\r\nPrepare "+Items(Value(draft,"prepare")).Length+" · Macro "+Items(Value(draft,"macro")).Length+" · Cleanup "+Items(Value(draft,"cleanup")).Length+" · "+Items(Value(inspection,"macro_sources")).Length+" macro revisions"+(changedSources>0?" · "+changedSources+" changed or missing; saved steps retained":"");
    nextReadout.Text=ReadoutPiece(Value(work,"next")==null?"Next":"Next · locked bookmark",Map(Value(work,"next")));policyReadout.Text="Protection: "+Items(Value(work,"protected")).Length+" orbits / "+Items(Value(work,"position_locks")).Length+" positions\n"+(Object.Equals(Value(Workspace,"prefix"),true)?"Every turn":"Final result")+" · reuse not checked";tips.SetToolTip(policyReadout,"The currently protected orbits and captured positions stay fixed. Loading this work sheet does not certify these steps; review the complete operation again.");
    comparison.SuspendLayout();while(comparison.Controls.Count>0){Control old=comparison.Controls[0];comparison.Controls.Remove(old);old.Dispose();}comparison.RowStyles.Clear();comparison.RowCount=0;
    Action<int,string,string,string,string,string> add=delegate(int row,string label,string saved,string now,string savedDetail,string nowDetail){comparison.RowCount=row+1;comparison.RowStyles.Add(new RowStyle(SizeType.AutoSize));string[] texts={label,saved,now};for(int col=0;col<3;col++){var text=new Label{Text=texts[col],AutoSize=true,Dock=DockStyle.Fill,Margin=new Padding(3,7,10,7),Padding=Padding.Empty,AccessibleName=label+" · "+(col==1?"Saved":col==2?"Now":"Field")};comparison.Controls.Add(text,col,row);if(col>0)SheetCopyMenu(text,col==1?savedDetail:nowDetail);}};
    add(0,"Compared field","SAVED","NOW","Saved method inputs","Current workspace inputs");int rowIndex=1;foreach(var value in Items(Value(inspection,"rows"))){var row=Map(value);string key=Text(Value(row,"key")),state=Text(Value(row,"status"));if(!unchanged.Checked&&state=="same"&&!new[]{"current","target","roles"}.Contains(key))continue;string flag=state=="same"?"":state=="unknown"?" · not recorded":state=="missing"?" · missing now":" · changed";add(rowIndex++,Text(Value(row,"label"))+flag,SheetRowText(row,"saved"),SheetRowText(row,"current"),SheetRowDetail(row,"saved"),SheetRowDetail(row,"current"));}comparison.ResumeLayout(true);
    string selectedTab=details.SelectedTab==null?null:details.SelectedTab.Text;
    while(details.TabPages.Count>0){var tab=details.TabPages[0];details.TabPages.Remove(tab);tab.Dispose();}foreach(string phase in new[]{"prepare","macro","cleanup"}){var tab=new TabPage(Char.ToUpperInvariant(phase[0])+phase.Substring(1));var steps=Items(Value(draft,phase));tab.Controls.Add(SheetReadout(steps.Length==0?"No fixed steps":String.Join("\r\n",steps.Select((step,index)=>(index+1)+". "+StepDetails(step)).ToArray()),"Saved "+phase+" fixed steps"));details.TabPages.Add(tab);if(selectedTab==null&&steps.Length>0)selectedTab=tab.Text;}
    var reference=new TabPage("Reference");reference.Controls.Add(SheetReadout("Saved explicit reference word\r\n"+(Items(Value(sheet,"reference")).Length==0?"Identity":String.Join(" ",Items(Value(sheet,"reference")).Select(Text).ToArray())),"Saved exact reference word"));details.TabPages.Add(reference);
    var sources=new List<string>();foreach(var item in Items(Value(inspection,"macro_sources"))){var source=Map(item);string id=Text(Value(source,"id"));var macro=Items(Value(work,"library")).Select(Map).FirstOrDefault(record=>Text(Value(record,"id"))==id);string title=macro==null?"Missing library entry":Text(Value(macro,"name"));sources.Add(title+" · revision "+Text(Value(source,"version"))+" · "+Text(Value(source,"phase"))+"\r\n"+Text(Value(source,"status"))+": "+Text(Value(source,"reason"))+"\r\nCanonical macro "+id+"; records "+(Number(Value(source,"start"))+1)+"–"+(Number(Value(source,"start"))+Number(Value(source,"count"))));}
    var provenance=new TabPage("Macro revisions");provenance.Controls.Add(SheetReadout(sources.Count>0?String.Join("\r\n",sources.ToArray()):Object.Equals(Value(inspection,"legacy"),true)?"Historical macro revisions were not recorded. The original fixed steps are retained.":"These steps contain no recorded library insertions.","Saved macro revisions and exact recipe status"));details.TabPages.Add(provenance);StyleTool(details);
    if(selectedTab!=null)foreach(TabPage tab in details.TabPages)if(tab.Text==selectedTab)details.SelectedTab=tab;
    var notices=new List<string>();if(Object.Equals(Value(inspection,"legacy"),true)||!valid)notices.Add(Text(Value(inspection,"note")));if(!sameOrbit)notices.Add("Method orbit differs. Loading keeps the current orbit and the saved fixed steps.");if(token.Length==0)notices.Add("Refresh comparison before loading.");if(failureNotice!=null)notices.Add(failureNotice);status.Text=String.Join("\r\n",notices.Where(text=>text.Length>0).ToArray());load.Enabled=valid&&token.Length>0&&!applying&&failureNotice==null;
   };
   unchanged.CheckedChanged+=delegate{render();};
   dialog.FormClosing+=delegate(object sender,FormClosingEventArgs e){if(applying&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;status.Text="Waiting for the current request. No further action was queued.";}};
   load.Click+=async delegate{if(applying)return;string confirmation=Text(Value(displayed,"confirmation"));if(confirmation.Length==0){reject("Refresh comparison before loading.");return;}applying=true;load.Enabled=refresh.Enabled=cancel.Enabled=false;try{bool accepted=await Send(LocalApi.D("action","template-use","name",name,"confirmation",confirmation,"confirm_inputs",true));applying=false;if(dialog.IsDisposed)return;if(accepted)dialog.Close();else reject(feedback.Text+"\r\nComparison retained. Refresh before retrying.");}catch(Exception error){if(!dialog.IsDisposed)reject(error.Message);}finally{applying=false;if(!dialog.IsDisposed)refresh.Enabled=cancel.Enabled=true;}};
   refresh.Click+=async delegate{if(applying)return;applying=true;load.Enabled=refresh.Enabled=cancel.Enabled=false;try{bool accepted=await Send(LocalApi.D("action","template-inspect","name",name));if(dialog.IsDisposed)return;if(accepted&&lastCommandResult!=null){displayed=lastCommandResult;failureNotice=null;applying=false;render();}else reject(feedback.Text);}catch(Exception error){if(!dialog.IsDisposed)reject(error.Message);}finally{applying=false;if(!dialog.IsDisposed)refresh.Enabled=cancel.Enabled=true;}};
   render();dialog.Shown+=delegate{cancel.Focus();};ShowOwned(dialog);
  }
 }
